def is_valid_isbn10(s: str) -> bool:
    # Remove hyphens
    cleaned = s.replace('-', '')

    # Must have exactly 10 characters
    if len(cleaned) != 10:
        return False

    # Check that first 9 are digits and last is digit or 'X'
    for i in range(9):
        if not cleaned[i].isdigit():
            return False

    if not (cleaned[9].isdigit() or cleaned[9] == 'X'):
        return False

    # Calculate the weighted sum
    total = 0
    for i in range(10):
        if cleaned[i] == 'X':
            digit = 10
        else:
            digit = int(cleaned[i])
        total += (10 - i) * digit

    return total % 11 == 0
